import "./Header.scss";
import Logo from "../../assets/images/Logo.png";
import { Link } from "react-router-dom";

const Header = ({ activeSection }) => {
  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <div className="header-container">
      <div className="header-items">
        <Link className="logo-link" to="/">
          <img className="header-logo" src={Logo} alt="logo" />
        </Link>
      </div>

      <div className="header-items">
        <ul className="header-menu">
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "TrangChu" ? "active" : ""}`}
              onClick={() => scrollToSection("TrangChu")}
            >
              Trang chủ
            </button>
          </li>
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "GioiThieu" ? "active" : ""}`}
              onClick={() => scrollToSection("GioiThieu")}
            >
              Giới thiệu
            </button>
          </li>
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "LopHoc" ? "active" : ""}`}
              onClick={() => scrollToSection("LopHoc")}
            >
              Các lớp học
            </button>
          </li>
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "DangKyLop" ? "active" : ""}`}
              onClick={() => scrollToSection("DangKyLop")}
            >
              Đăng ký lớp
            </button>
          </li>
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "LuuY" ? "active" : ""}`}
              onClick={() => scrollToSection("LuuY")}
            >
              Lưu ý
            </button>
          </li>
          <li className="header-menu__item">
            <button
              className={`header-menu__item-link ${activeSection === "LienHe" ? "active" : ""}`}
              onClick={() => scrollToSection("LienHe")}
            >
              Liên hệ
            </button>
          </li>
        </ul>
      </div>

      <div className="header-items">
        <Link to="/login" className="login">
          Đăng nhập
        </Link>

        <Link to="/register" className="register">
          Đăng ký
        </Link>
      </div>
    </div>
  );
};

export default Header;
